using System;using System.IO;using System.Linq;using NUnit.Framework;using UnityEngine;using IdleIntelligence.Core;
namespace IdleIntelligence.Tests {
 [Serializable]public sealed class ItemV3MaterialItem{public string id,type;public int rarity,level,forge;public bool missing;public double[] basis,used;}
 [Serializable]public sealed class ItemV3MaterialStep{public string action,id;public int quantity,prestiges,axioms;public bool allowed,same,forgeActive,analysis;public double roll,at,progress,analysisFactor;public double[] quoted,allocated,refundRemainders,salvageRemainders;public long fragments,additional;public long[] components;public string[] nodes;public NumberData data,counter;public ItemV3MaterialItem[] inventory;}
 [Serializable]public sealed class ItemV3MaterialFlow{public string name,mode;public bool research,prepared;public ItemV3MaterialStep[] steps;}
 [Serializable]public sealed class ItemV3MaterialCases{public string sourceHash;public bool prepared,productionEnabled;public ItemV3MaterialFlow[] flows;}
 public sealed class ItemSystemV3MaterialTests {
  static ItemV3MaterialCases Cases()=>JsonUtility.FromJson<ItemV3MaterialCases>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/ItemV3MaterialCases.json")));
  static void Near(ScientificNumber actual,NumberData row,string context){var expected=ScientificNumber.FromData(row);if(expected.IsZero)Assert.That(actual.IsZero,Is.True,context);else Assert.That(actual.Log10(),Is.EqualTo(expected.Log10()).Within(2e-10),context);}
  static GameState Prepared(string mode,bool research){var s=Game.New(1000,"prepared-material-cycle-reference");s.Legacy.prepared=true;s.Data=ScientificNumber.From(1e12);if(mode!="normal")s.ItemSystemV3=new ItemV3State();s.Workshop.nodes=mode=="maximum"?new[]{"W06","W07","W10"}:new[]{"W06","W07"};s.Research[Array.FindIndex(Balance.Research,d=>d.Id=="blueprints")]=1;if(research)s.Research[Array.FindIndex(Balance.Research,d=>d.Id=="materialRecycling")]=1;s.Workshop.learned[Workshop.Index("quantum-chip")]=true;s.Workshop.components=Enumerable.Repeat(1000000L,ItemBalance.ComponentIds.Length).ToArray();s.Workshop.modules=Enumerable.Repeat(10000L,ItemBalance.Modules.Length).ToArray();string[] types=mode=="none"?Array.Empty<string>():mode=="manufacturing"?new[]{"manufacturing-controller"}:mode=="probe"?new[]{"recycling-probe"}:mode=="pair"?new[]{"manufacturing-controller","recycling-probe"}:new[]{"manufacturing-controller","recycling-probe","diagnostic-adapter"};foreach(string type in types){s=RetentionRules.CreateItem(s,type,mode=="maximum"?5:0);var item=s.Workshop.inventory.Last();if(mode=="maximum"){item.level=(int)ItemV3Balance.Get("levelMax");item.forge=(int)ItemV3Balance.Get("forgeMax");}s=Workshop.Equip(s,item.id,Workshop.EquipmentSlot(s,item.id));}if(mode=="no-items")s.Challenges.Run=new ChallengeRun{id="no-items",stage=1};return s;}
  static GameState Fund(GameState state,bool pending){var s=state.Copy();var cycle=ScientificNumber.From(1e12);s.Prestige.Total=s.Prestige.Total.Add(cycle.Subtract(s.Prestige.Cycle));s.Prestige.Cycle=cycle;s.Prestige.Free=cycle.Subtract(s.Prestige.Spent);s.Prestige.Entitlement=cycle.Times(pending?2:1);s.Prestige.known=PrestigeBalance.Nodes.Take(30).Select(n=>n.Id).ToArray();s.ItemSystemV3.axiomDiscovered=true;s.ItemSystemV3.axiomDiscoveryAt=1000;return s;}
  [Test]public void ActualCraftFusionUpgradeForgeSalvageAndResetsMatchSourceMaterialFlows(){var cases=Cases();Assert.That(cases.sourceHash,Is.EqualTo(ItemV3Balance.SourceHash));Assert.That(cases.productionEnabled,Is.False);Assert.That(cases.flows.Length,Is.EqualTo(31));foreach(var flow in cases.flows){var s=Prepared(flow.mode,flow.research);foreach(var step in flow.steps){var before=s;string label=flow.name+" "+step.action;switch(step.action){
   case "craft":var craft=Workshop.BatchQuote(s,"quantum-chip",step.quantity);Assert.That(craft.Allowed,Is.EqualTo(step.allowed),label);Assert.That(craft.Components,Is.EqualTo(step.quoted),label+" actual paid inputs");s=Workshop.CraftBatch(s,"quantum-chip",step.quantity);break;
   case "rare-gift":case "common-gift":case "uncommon-gift":for(int n=0;n<step.quantity;n++)s=RetentionRules.CreateItem(s,"quantum-chip",step.action=="rare-gift"?2:step.action=="uncommon-gift"?1:0);break;
   case "seed-cap":s=s.Copy();s.Meta.axioms[Array.FindIndex(MetaBalance.Axioms,d=>d.Id=="C05")]=3;foreach(var item in s.Workshop.inventory.Where(i=>i.type=="quantum-chip")){item.materialBasis[0]=100;item.materialBasis[1]=20;item.recoveryUsed[0]=85;item.recoveryUsed[1]=17;item.missingMaterialBasis=false;}break;
   case "seed-half":if(s.ItemSystemV3!=null){s=s.Copy();s.ItemSystemV3.recyclingFragmentProgress=.5;}break;
   case "salvage":case "duplicate":var target=s.Workshop.inventory.FirstOrDefault(i=>i.id==step.id);if(target!=null&&!target.locked&&!target.challengeCopy&&!s.Workshop.equipped.Contains(target.id)&&ItemSystemV3.Enabled(s)){double rate=Math.Min(MetaBalance.RecoveryCap,(MetaBalance.RecoveryBase+MetaBalance.RecoveryStep*MetaRules.Level(s,"C05"))*(1+ChallengeRules.Bonus(s,"closed-supply-chain")));Assert.That(Enumerable.Range(0,ItemBalance.ComponentIds.Length).Select(c=>ItemSystemV3.SalvageAllocated(target.materialBasis[c],target.recoveryUsed[c],rate)),Is.EqualTo(step.allocated).Within(1e-10),label+" allocated return excludes old fractional carry");Assert.That(ItemSystemV3.SalvageFragments(s,target).gained,Is.EqualTo(step.additional),label+" separate ordinary RNG and extra fragments");}s=MetaAutomation.Salvage(s,step.id,step.roll);Assert.That(!ReferenceEquals(s,before),Is.EqualTo(step.allowed),label+" irreversible guard");break;
   case "upgrade":var upgradeItem=s.Workshop.inventory.First(i=>i.id==step.id);var quote=Workshop.UpgradeQuote(s,upgradeItem);Assert.That(quote.Allowed,Is.EqualTo(step.allowed),label);Assert.That(quote.Components,Is.EqualTo(step.quoted),label+" actual upgrade payment");s=Workshop.Upgrade(s,step.id,s.Workshop.revision);break;
   case "forge":s=Industry.QueueForge(s,step.id);Assert.That(!ReferenceEquals(s,before),Is.EqualTo(step.allowed),label);Assert.That(step.allowed,Is.True,label+" this is a real paid start");break;
   case "finish-forge":s=Game.Advance(s,step.at);break;
   case "fuse":s=Workshop.Fuse(s,s.Workshop.inventory.Where(i=>i.type=="quantum-chip").Take(3).Select(i=>i.id).ToArray());Assert.That(!ReferenceEquals(s,before),Is.EqualTo(step.allowed),label);break;
   case "lock":s=Workshop.Lock(s,step.id);break;
   case "prestige":case "axiom":s=Game.Advance(s,before.SavedAt+60000);s=Fund(s,step.action=="prestige");var ready=s;s=step.action=="prestige"?PrestigeRules.Reset(s):MetaRules.AxiomReset(s);Assert.That(!ReferenceEquals(s,ready),Is.EqualTo(step.allowed),label);Assert.That(step.allowed,Is.True,label+" actual reset");break;
   case "analysis":s=s.Copy();s.Research[Array.FindIndex(Balance.Research,d=>d.Id=="materialAnalysis")]=3;s=MaterialAnalysis.Start(s,0);Assert.That(s.Workshop.hasAnalysis,Is.EqualTo(step.allowed),label);break;
   case "finish-analysis":s=Game.Advance(s,step.at);break;
   default:Assert.Fail("Unknown source material action "+step.action);break;
  }Assert.That(ReferenceEquals(s,before),Is.EqualTo(step.same),label+" no partial transaction");Near(s.Data,step.data,label+" data wallet");Assert.That(s.Workshop.components,Is.EqualTo(step.components),label+" component wallet");Assert.That(s.Workshop.recyclingRemainders,Is.EqualTo(step.refundRemainders).Within(1e-10),label+" refund fractions");Assert.That(s.Meta.salvageRemainders,Is.EqualTo(step.salvageRemainders).Within(1e-10),label+" salvage fractions");Assert.That(s.Workshop.fragments,Is.EqualTo(step.fragments),label+" actual fragments");Assert.That(s.ItemSystemV3?.recyclingFragmentProgress??0,Is.EqualTo(step.progress).Within(1e-12),label+" fragment currency and resets");if(s.ItemSystemV3!=null)Near(s.ItemSystemV3.componentsProduced,step.counter,label+" recovery is not production K");Assert.That(s.Workshop.nodes,Is.EqualTo(step.nodes),label);Assert.That(s.Prestige.resets,Is.EqualTo(step.prestiges),label);Assert.That(s.Meta.resets,Is.EqualTo(step.axioms),label);Assert.That(s.Industry.foundries.Any(f=>f.active!=null),Is.EqualTo(step.forgeActive),label);Assert.That(s.Workshop.hasAnalysis,Is.EqualTo(step.analysis),label);Assert.That(s.Workshop.hasAnalysis?s.Workshop.analysis.combination:0,Is.EqualTo(step.analysisFactor).Within(1e-10),label+" closed-loop paid analysis factor");Assert.That(s.Workshop.inventory.Length,Is.EqualTo(step.inventory.Length),label);for(int n=0;n<step.inventory.Length;n++){var actual=s.Workshop.inventory[n];var expected=step.inventory[n];Assert.That(actual.id,Is.EqualTo(expected.id),label);Assert.That(actual.type,Is.EqualTo(expected.type),label);Assert.That(actual.rarity,Is.EqualTo(expected.rarity),label);Assert.That(actual.level,Is.EqualTo(expected.level),label);Assert.That(actual.forge,Is.EqualTo(expected.forge),label);Assert.That(actual.materialBasis,Is.EqualTo(expected.basis).Within(1e-10),label+" paid basis only");Assert.That(actual.recoveryUsed,Is.EqualTo(expected.used).Within(1e-10),label+" already allocated returns");}ItemSystemV3.Validate(s);Workshop.Validate(s);}}}
  [Test]public void InvalidFractionOrOverflowCannotConsumeItemOrPay(){var s=Prepared("probe",false);s=RetentionRules.CreateItem(s,"quantum-chip",2);string id=s.Workshop.inventory.Last().id;var bad=s.Copy();bad.ItemSystemV3.recyclingFragmentProgress=double.NaN;Assert.Throws<FormatException>(()=>MetaAutomation.Salvage(bad,id,0));Assert.That(bad.Workshop.inventory.Any(i=>i.id==id),Is.True);var overflow=s.Copy();overflow.Workshop.components[0]=9007199254740991L;overflow.Workshop.inventory.Last().materialBasis[0]=10;Assert.That(MetaAutomation.Salvage(overflow,id,0),Is.SameAs(overflow));Assert.That(overflow.Workshop.inventory.Last().id,Is.EqualTo(id));var copied=s.Copy();copied.ItemSystemV3.recyclingFragmentProgress=.75;Assert.That(s.ItemSystemV3.recyclingFragmentProgress,Is.EqualTo(0));}
 }
}
